# Generate a graph with 13 vertices and between 29 and 39 edges
edges = []
count = 0
target = 30  # Pick 30 edges, which is between 29 and 39

for u in range(13):
    for v in range(u+1, 13):
        if count < target:
            edges.append((u, v))
            count += 1
        else:
            break
    if count >= target:
        break

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Verify all edges satisfy 0 <= u < v < 13
for u, v in edges:
    assert 0 <= u < v < 13, f"Invalid edge: ({u}, {v})"

print("All edges are valid!")
